/// Fills the editor colors from the scheme; unmapped fields keep `e`'s value.
fn editor(mut e: EditorColors) -> EditorColors {
    e.background = px(0x404040FF); // TEXT.bg
    e.text = px(0x9BC28EFF); // TEXT.fg
    e.caret = px(0x00FF00FF); // CARET_COLOR
    e.caret_row = px(0x282828FF); // CARET_ROW_COLOR
    e.line_number = px(0x6DA0A1FF); // LINE_NUMBERS_COLOR
    e.line_number_caret = px(0xA4A3A3FF); // LINE_NUMBER_ON_CARET_ROW_COLOR
    e.selection = px(0x348D34FF); // SELECTION_BACKGROUND
    e.background_panel = px(0x46484AFF); // DOCUMENTATION_COLOR
    e.search_result = px(0xF3F34DFF); // TEXT_SEARCH_RESULT_ATTRIBUTES.bg
    e.rename_occurrence = px(0x525259FF); // IDENTIFIER_UNDER_CARET_ATTRIBUTES.bg
    e.matched_brace = px(0x495F2AFF); // MATCHED_BRACE_ATTRIBUTES.bg
    e.indent_guide = px(0x505050FF); // INDENT_GUIDE
    e.error_effect = px(0xBC3F3CFF); // ERRORS_ATTRIBUTES.effect
    e.warning_effect = px(0xFFFF00FF); // WARNING_ATTRIBUTES.stripe
    e.weak_warning_effect = px(0xCCCCCCFF); // INFO_ATTRIBUTES.effect
    e.breakpoint_line = px(0x3A4A6FFF); // BREAKPOINT_ATTRIBUTES.bg
    e.execution_line = px(0x1A65A5FF); // EXECUTIONPOINT_ATTRIBUTES.bg
    e.inline_value = px(0x666D75FF); // DEBUGGER_INLINED_VALUES.fg
    e.error_stripe = px(0x9E2927FF); // ERRORS_ATTRIBUTES.stripe
    e.warning_stripe = px(0xFFFF00FF); // WARNING_ATTRIBUTES.stripe
    e.string = px(0x34B434FF); // DEFAULT_STRING.fg
    e.number = px(0xF971BBFF); // DEFAULT_NUMBER.fg
    e.keyword = px(0xCA9E4DFF); // DEFAULT_KEYWORD.fg
    e.type_name = px(0xF8F870FF); // TYPE_PARAMETER_NAME_ATTRIBUTES.fg
    e.annotation = px(0x7A8FD9FF); // DEFAULT_METADATA.fg
    e.property = px(0xB9B9B9FF); // DEFAULT_INSTANCE_FIELD.fg
    e.punctuation = px(0xCC7832FF); // DEFAULT_COMMA.fg
    e.comment = px(0xE54242FF); // DEFAULT_LINE_COMMENT.fg
    e.tag = px(0xB8AE5BFF); // XML_TAG_NAME.fg
    e.attribute = px(0xA0A0A0FF); // XML_ATTRIBUTE_NAME.fg
    e.variable = px(0xFFC66DFF); // DEFAULT_FUNCTION_DECLARATION.fg
    e.invalid = px(0x9F0E44FF); // BAD_CHARACTER.fg
    // Kept at the measured value: constant, search_result_current.
    e
}
